using MessagePack.Formatters;

public class A5_F1_GeneratedMessagePackFormatterTests(ITestOutputHelper logger)
{
    private static MessagePackSerializerOptions CreateOptions()
    {
        return MessagePackSerializerOptions.Standard.WithResolver(
            MessagePack.Resolvers.CompositeResolver.Create(
                new IMessagePackFormatter[] { new A5F1PointFormatter() },
                new IFormatterResolver[] { MessagePackSerializerOptions.Standard.Resolver }));
    }

    [Fact]
    public void A5_F1_GeneratedFormatter_RoundtripsValue()
    {
        A5F1Point value = new() { X = 42, Name = "hello" };
        A5F1Point after = this.Roundtrip(value);
        Assert.Equal(42, after.X);
        Assert.Equal("hello", after.Name);
        Assert.Equal(value, after);
    }

    [Fact]
    public void A5_F1_GeneratedFormatter_RoundtripsDefaultValue()
    {
        A5F1Point value = new() { X = -7, Name = null };
        A5F1Point after = this.Roundtrip(value);
        Assert.Equal(-7, after.X);
        Assert.Null(after.Name);
    }

    private T Roundtrip<T>(T value)
    {
        MessagePackSerializerOptions options = CreateOptions();
        byte[] serialized = MessagePackSerializer.Serialize(value, options);
        logger.WriteLine(MessagePackSerializer.ConvertToJson(serialized, options));
        return MessagePackSerializer.Deserialize<T>(serialized, options);
    }
}

[MessagePackObject]
public struct A5F1Point
{
    [Key(0)]
    public int X { get; set; }

    [Key(1)]
    public string? Name { get; set; }
}

